<script setup lang="ts">
import { apiPath, mediaPath } from '@/utils/api'
import { Save, UploadCloud, LoaderCircle } from 'lucide-vue-next'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Select } from '@/components/ui/select'
import { Textarea } from '@/components/ui/textarea'
import { Alert } from '@/components/ui/alert'
import type { Category, GisLocation } from '@/types/gis'

const props=defineProps<{categories:Category[];initial?:Partial<GisLocation>;submitLabel?:string}>()
const emit=defineEmits<{submit:[Record<string,unknown>]}>()
const uploading=ref<'before'|'after'|null>(null)
const error=ref('')
const form=reactive({
 name:props.initial?.name||'', category_id:props.initial?.category_id||props.categories[0]?.id||0,
 district:props.initial?.district||'', address:props.initial?.address||'', condition:props.initial?.condition||'unassessed',
 latitude:Number(props.initial?.latitude||-6.1754), longitude:Number(props.initial?.longitude||106.8272),
 road_width:props.initial?.road_width??'', speed_bump_units:props.initial?.speed_bump_units??'', speed_bump_m:props.initial?.speed_bump_m??'', endcap_units:props.initial?.endcap_units??'',
 before_photo_url:props.initial?.before_photo_url||'', after_photo_url:props.initial?.after_photo_url||'', notes:props.initial?.notes||'',
})
watch(()=>props.categories,()=>{if(!form.category_id&&props.categories[0])form.category_id=props.categories[0].id},{immediate:true})
function pointChanged(p:{latitude:number;longitude:number}){form.latitude=Number(p.latitude.toFixed(7));form.longitude=Number(p.longitude.toFixed(7))}
async function upload(file:File,slot:'before'|'after'){
 uploading.value=slot;error.value=''
 try{const fd=new FormData();fd.append('file',file);const out=await $fetch<{url:string}>(apiPath('/api/admin/uploads'),{method:'POST',body:fd});if(slot==='before')form.before_photo_url=out.url;else form.after_photo_url=out.url}
 catch(e:any){error.value=e?.data?.statusMessage||'Upload foto gagal.'}finally{uploading.value=null}
}
function fileChanged(event:Event,slot:'before'|'after'){const file=(event.target as HTMLInputElement).files?.[0];if(file)void upload(file,slot)}
function submit(){error.value='';if(!form.name.trim())return error.value='Nama lokasi wajib diisi.';if(!Number(form.category_id))return error.value='Kategori wajib dipilih.';emit('submit',{...form,category_id:Number(form.category_id),latitude:Number(form.latitude),longitude:Number(form.longitude),road_width:form.road_width===''?null:Number(form.road_width),speed_bump_units:form.speed_bump_units===''?null:Number(form.speed_bump_units),speed_bump_m:form.speed_bump_m===''?null:Number(form.speed_bump_m),endcap_units:form.endcap_units===''?null:Number(form.endcap_units)})}
</script>
<template><form class="space-y-6" @submit.prevent="submit"><Alert v-if="error" variant="destructive">{{error}}</Alert><div class="grid gap-6 xl:grid-cols-[1fr_420px]"><div class="space-y-6"><Card><CardHeader><CardTitle class="text-base">Informasi Lokasi</CardTitle><CardDescription>Data utama yang akan ditampilkan pada peta.</CardDescription></CardHeader><CardContent class="grid gap-4 sm:grid-cols-2"><div class="space-y-2 sm:col-span-2"><Label>Nama / Lokasi Kegiatan</Label><Input v-model="form.name" placeholder="Jl. ..." /></div><div class="space-y-2"><Label>Kategori</Label><Select v-model="form.category_id"><option v-for="cat in categories" :key="cat.id" :value="cat.id">{{cat.name}}</option></Select></div><div class="space-y-2"><Label>Kondisi</Label><Select v-model="form.condition"><option value="good">Baik / Sesuai</option><option value="bad">Tidak Baik / Tidak Sesuai</option><option value="unassessed">Belum Dinilai</option></Select></div><div class="space-y-2"><Label>Kecamatan</Label><Input v-model="form.district" placeholder="Koja" /></div><div class="space-y-2"><Label>Alamat tambahan</Label><Input v-model="form.address" /></div><div class="space-y-2"><Label>Latitude</Label><Input v-model="form.latitude" type="number" step="any" /></div><div class="space-y-2"><Label>Longitude</Label><Input v-model="form.longitude" type="number" step="any" /></div></CardContent></Card><Card><CardHeader><CardTitle class="text-base">Data Teknis</CardTitle><CardDescription>Opsional. Field ini cocok untuk kategori speed bump.</CardDescription></CardHeader><CardContent class="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><div class="space-y-2"><Label>Lebar Jalan (m)</Label><Input v-model="form.road_width" type="number" step="any" /></div><div class="space-y-2"><Label>Speed Bump (unit)</Label><Input v-model="form.speed_bump_units" type="number" step="any" /></div><div class="space-y-2"><Label>Speed Bump (m)</Label><Input v-model="form.speed_bump_m" type="number" step="any" /></div><div class="space-y-2"><Label>Endcap</Label><Input v-model="form.endcap_units" type="number" step="any" /></div><div class="space-y-2 sm:col-span-2 lg:col-span-4"><Label>Catatan</Label><Textarea v-model="form.notes" /></div></CardContent></Card><Card><CardHeader><CardTitle class="text-base">Dokumentasi</CardTitle><CardDescription>Foto sebelum dan sesudah dapat diunggah dari form ini.</CardDescription></CardHeader><CardContent class="grid gap-5 sm:grid-cols-2"><div class="space-y-2"><Label>Foto Sebelum</Label><div v-if="form.before_photo_url" class="overflow-hidden rounded-lg border"><img :src="mediaPath(form.before_photo_url)" class="h-40 w-full object-cover" /></div><label class="flex cursor-pointer items-center justify-center gap-2 rounded-md border border-dashed p-3 text-sm text-muted-foreground hover:bg-muted"><LoaderCircle v-if="uploading==='before'" class="size-4 animate-spin" /><UploadCloud v-else class="size-4" />Pilih foto<input class="hidden" type="file" accept="image/*" @change="fileChanged($event,'before')" /></label></div><div class="space-y-2"><Label>Foto Sesudah</Label><div v-if="form.after_photo_url" class="overflow-hidden rounded-lg border"><img :src="mediaPath(form.after_photo_url)" class="h-40 w-full object-cover" /></div><label class="flex cursor-pointer items-center justify-center gap-2 rounded-md border border-dashed p-3 text-sm text-muted-foreground hover:bg-muted"><LoaderCircle v-if="uploading==='after'" class="size-4 animate-spin" /><UploadCloud v-else class="size-4" />Pilih foto<input class="hidden" type="file" accept="image/*" @change="fileChanged($event,'after')" /></label></div></CardContent></Card></div><div class="space-y-4 xl:sticky xl:top-6 xl:self-start"><Card><CardHeader><CardTitle class="text-base">Pilih Titik</CardTitle><CardDescription>Klik pada peta untuk mengisi koordinat.</CardDescription></CardHeader><CardContent><ClientOnly><MapPicker :latitude="Number(form.latitude)" :longitude="Number(form.longitude)" @change="pointChanged" /></ClientOnly></CardContent></Card><Button type="submit" size="lg" class="w-full" :disabled="!!uploading"><Save class="size-4" />{{submitLabel||'Simpan lokasi'}}</Button></div></div></form></template>
